/**
 * Dispatch weapon instance events to main thread.
 * Reads from pendingWeaponEvents queue and sends events via physicEvent.
 *
 * Event target format: `weapon_${weaponInstanceId}_${eventType}`
 * Examples:
 * - `weapon_0_explode` - Weapon instance 0 exploded
 * - `weapon_1_hit` - Weapon instance 1 hit a target
 * - `weapon_2_fire` - Weapon instance 2 fired
 */
export function manageWeaponInstanceEvents(): void;
